example:
// bynk.toml
[unstable]
allow = ["bynk.cloudflare.RateLimit"]

// login.bynk
context login

consumes bynk.cloudflare { RateLimit }

capability LoginLimit = RateLimit @limit(20) @period(30.seconds)    // ✗ a window is 10 or 60 seconds
capability LoginLimit = RateLimit @limit(20) @period(60.seconds)    // ✓
